//go:build slimdict

package main

import (
	"archive/zip"
	"bytes"
	_ "embed"

	"github.com/ikawaha/kagome-dict/dict"
)

//go:embed neologd-slim.dict
var dictdata []byte

// systemDict returns the slimmed-down dictionary generated by cmd/slimdict.
// Unlike ipaneologd.Dict() it reads the zip out of the embedded bytes as they
// are, so the dictionary is not copied onto the heap while loading.
func systemDict() *dict.Dict {
	r := bytes.NewReader(dictdata)
	zr, err := zip.NewReader(r, r.Size())
	if err != nil {
		panic(err.Error())
	}
	d, err := dict.Load(zr, true)
	if err != nil {
		panic(err.Error())
	}
	return d
}
